// 1. 雪花算法实现
public class SnowflakeIdGenerator {
    // 起始时间戳 (2024-01-01 00:00:00)
    private static final long START_TIMESTAMP = 1704067200000L;
    // 各部分位数
    private static final long WORKER_ID_BITS = 5L;
    private static final long DATACENTER_ID_BITS = 5L;
    private static final long SEQUENCE_BITS = 12L;
    // 最大值
    private static final long MAX_WORKER_ID = ~(-1L << WORKER_ID_BITS);
    private static final long MAX_DATACENTER_ID = ~(-1L << DATACENTER_ID_BITS);
    private static final long SEQUENCE_MASK = ~(-1L << SEQUENCE_BITS);
    // 左移位数
    private static final long WORKER_ID_SHIFT = SEQUENCE_BITS;
    private static final long DATACENTER_ID_SHIFT = SEQUENCE_BITS + WORKER_ID_BITS;
    private static final long TIMESTAMP_SHIFT = SEQUENCE_BITS + WORKER_ID_BITS + DATACENTER_ID_BITS;

    private long workerId;
    private long datacenterId;
    private long sequence = 0L;
    private long lastTimestamp = -1L;

    public synchronized long nextId() {
        long current = System.currentTimeMillis();
        if (current < lastTimestamp) {
            throw new RuntimeException("时钟回拨");
        }
        if (current == lastTimestamp) {
            sequence = (sequence + 1) & SEQUENCE_MASK;
            if (sequence == 0) {
                current = waitNextMillis(lastTimestamp);
            }
        } else {
            sequence = 0L;
        }
        lastTimestamp = current;
        return ((current - START_TIMESTAMP) << TIMESTAMP_SHIFT)
            | (datacenterId << DATACENTER_ID_SHIFT)
            | (workerId << WORKER_ID_SHIFT)
            | sequence;
    }
}

// 2. 号段模式实现
@Service
public class SegmentIdGenerator {
    private final AtomicLong currentId = new AtomicLong(0);
    private final AtomicLong maxId = new AtomicLong(0);
    private final IdAllocMapper idAllocMapper;

    public long nextId() {
        long id = currentId.incrementAndGet();
        if (id > maxId.get()) {
            synchronized (this) {
                if (id > maxId.get()) {
                    // 从DB批量获取新号段
                    IdSegment segment = idAllocMapper.allocSegment("order_id");
                    currentId.set(segment.getStart());
                    maxId.set(segment.getEnd());
                    id = currentId.incrementAndGet();
                }
            }
        }
        return id;
    }
}

// 3. UUID生成
public class IdUtil {
    public static String uuid() {
        return UUID.randomUUID().toString().replace("-", "");
    }

    // 更短的ID
    public static String shortId() {
        return Long.toString(UUID.randomUUID().getMostSignificantBits(), 36)
            + Long.toString(UUID.randomUUID().getLeastSignificantBits(), 36);
    }
}
